Let me now think about crenellate signature: crenellate(x, z, w, d, y): boxes 1.4x1.3x1.1 along top edges. Implementation:

```js
function crenellate(x, z, w, d, y) {
  const nx = Math.max(2, Math.round(w / 2.4));
  const dxw = w / nx;
  for (let i = 0; i < nx; i++) {
    const ox = -w / 2 + (i + 0.5) * dxw;
    box(1.2, 1.4, 1.1, x + ox, y, z - d / 2 + 0.6, crenMat);
    box(1.2, 1.4, 1.1, x + ox, y, z + d / 2 - 0.6, crenMat);
  }
  const nz = Math.max(2, Math.round(d / 2.4));
  const dzw = d / nz;
  for (let j = 1; j < nz - 1; j++) {  // skip corners already covered
    const oz = -d / 2 + (j + 0.5) * dzw;
    box(1.1, 1.4, 1.2, x - w / 2 + 0.6, y, z + oz, crenMat);
    box(1.1, 1.4, 1.2, x + w / 2 - 0.6, y, z + oz, crenMat);
  }
}
```

