function archFrame(w, h, depth, hwr = 0.2, y0r = 0.5) {
  const shape = new THREE.Shape();
  shape.moveTo(-w / 2, 0);
  shape.lineTo(w / 2, 0);
  shape.lineTo(w / 2, h);
  shape.lineTo(-w / 2, h);
  shape.closePath();
  const hw = w * hwr;
  const y0 = h * y0r;
  const hole = new THREE.Path();
  hole.moveTo(-hw, 0);
  hole.lineTo(-hw, y0);
  hole.absarc(0, y0, hw, Math.PI, 0, true);
  hole.lineTo(hw, 0);
  hole.closePath();
  shape.holes.push(hole);
  const m = new THREE.Mesh(new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: false }), wallMat);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
```
