animate:
```js
function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  if (camAnim) {
    const u = Math.min((performance.now() - camAnim.t0) / camAnim.dur, 1);
    const e = u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
    camera.position.lerpVectors(camAnim.from, camAnim.to, e);
    camera.position.y += Math.sin(u * Math.PI) * Math.min(30, camAnim.from.distanceTo(camAnim.to) * 0.16);
    controls.target.lerpVectors(camAnim.fromT, camAnim.toT, e);
    camera.lookAt(controls.target);
    if (u >= 1) {
      camAnim = null;
      controls.enabled = true;
      bannerEl.classList.remove('on');
      if (auto) autoTimer = setTimeout(() => goTo(idx + 1), 5800);
    }
  }
  controls.update();
  markers.forEach((m, i) => {
    m.position.y = m.userData.by + Math.sin(t * 2.2 + i * 1.7) * 0.3;
    rings[i].scale.setScalar(1 + Math.sin(t * 2.6 + i) * 0.09);
  });
  jets.forEach((j, i) => { j.scale.y = 0.75 + Math.sin(t * 3.1 + i * 1.3) * 0.3; });
  renderer.render(scene, camera);
}
```
